if mibBuilder.loadTexts: tmnxLogTraceError.setDescription('[CAUSE] The tmnxLogTraceError notification is generated when a\n         critical level trace error has been detected by the software. There\n         are multiple triggers for such a trace error.\n\n         [EFFECT] Effect varies depending on the specific trigger.\n\n         [RECOVERY] Contact Nokia Support.')
tmnxLogEventThrottled = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 12, 0, 8)).setObjects(("TIMETRA-LOG-MIB", "tmnxLogThrottledEventID"), ("TIMETRA-LOG-MIB", "tmnxLogThrottledEvents"))
if mibBuilder.loadTexts: tmnxLogEventThrottled.setStatus('current')
if mibBuilder.loadTexts: tmnxLogEventThrottled.setDescription('A tmnxLogEventThrottled notification is generated at the end of the\n         throttling interval when one or more events are dropped because the\n         throttling limit was reached for that interval.')
tmnxSysLogTargetProblem = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 12, 0, 9)).setObjects(("TIMETRA-LOG-MIB", "tmnxSysLogTargetId"), ("TIMETRA-LOG-MIB", "tmnxSysLogTargetProblemDescr"))
if mibBuilder.loadTexts: tmnxSysLogTargetProblem.setStatus('current')
if mibBuilder.loadTexts: tmnxSysLogTargetProblem.setDescription('A tmnxSysLogTargetProblem notification is generated when a problem is\n         encountered when trying to deliver data to the syslog destination\n         identified by the tmnxSysLogTargetId.')
tmnxLogAccountingDataLoss = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 12, 0, 10)).setObjects(("TIMETRA-LOG-MIB", "tmnxLogFileIdRolloverTime"), ("TIMETRA-LOG-MIB", "tmnxLogFileIdRetainTime"), ("TIMETRA-LOG-MIB", "tmnxLogFileIdAdminLocation"), ("TIMETRA-LOG-MIB", "tmnxLogFileIdBackupLoc"), ("TIMETRA-LOG-MIB", "tmnxLogFileIdOperLocation"), ("TIMETRA-LOG-MIB", "tmnxLogFileIdLogId"), ("TIMETRA-LOG-MIB", "tmnxLogNotifyApInterval"))
if mibBuilder.loadTexts: tmnxLogAccountingDataLoss.setStatus('current')
if mibBuilder.loadTexts: tmnxLogAccountingDataLoss.setDescription('A tmnxLogAccountingDataLoss notification is generated\n         when an accounting file is still being written to\n         when the next interval ends.  The collection of\n         statistics for the past interval is immediately\n         stopped and collection is started for the next\n         interval.  There are missing records in the file\n         for this past interval.')
tmnxStdEventsReplayed = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 12, 0, 11)).setObjects(("TIMETRA-LOG-MIB", "tmnxStdDestAddrType"), ("TIMETRA-LOG-MIB", "tmnxStdDestAddr"), ("TIMETRA-LOG-MIB", "tmnxStdReplayStartEvent"), ("TIMETRA-LOG-MIB", "tmnxStdReplayEndEvent"), ("TIMETRA-LOG-MIB", "tmnxStdReplayStart"))
if mibBuilder.loadTexts: tmnxStdEventsReplayed.setStatus('current')
if mibBuilder.loadTexts: tmnxStdEventsReplayed.setDescription('A tmnxStdEventsReplayed notification is generated when\n         an SNMP trap target address is added to the RTM (tmnxVRtrID)\n         following a period when the address had been removed.\n         The value of tmnxStdReplayStartEvent is the SNMP notification\n         request ID of the first event that was replayed.  The value\n         of tmnxStdReplayEndEvent is the SNMP notification request ID of the\n         last missed event that was replayed.  The value of\n         tmnxStdReplayStart is the request ID of the first event for\n         which there was no route to the trap target address.')
tmnxLogEventOverrun = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 12, 0, 12)).setObjects(("TIMETRA-LOG-MIB", "tmnxLogThrottledEventID"), ("TIMETRA-LOG-MIB", "tmnxLogThrottledEvents"))
if mibBuilder.loadTexts: tmnxLogEventOverrun.setStatus('current')
if mibBuilder.loadTexts: tmnxLogEventOverrun.setDescription("[CAUSE] A tmnxLogEventOverrun notification is generated\n         at the end of the overrun throttling interval when one or more\n         events of the type specified by tmnxLogThrottledEventID were\n         dropped because the logger input stream's input queue limit\n         was exceeded.  The overrun throttling interval begins when the\n         input queue limit is first exceeded and ends when the number of\n         events in the input queue has dropped below an internal low\n         watermark.  At that point a tmnxLogEventOverrun notification is\n         generated for each event type that had one or more     events dropped\n         because of the input queue overrun. The number of dropped events\n         is specified by tmnxLogThrottledEvents.\n\n         [EFFECT] Logger events have been dropped and were not sent to any\n         log destination.  tmnxEventDropCount has been incremented for\n         each event dropped because of input queue overrun.\n\n         [RECOVERY] The specific event information of dropped events\n         cannot be recovered.  The frequency of input queue overruns\n         can be lessened by configuring as few event logs as possible,\n         especially those going to remote destinations such as file,\n         syslog and snmp notification logs.")
